import { useEffect, useRef, useState } from "react";

export interface LoadResult {
  /** Items produced by this page. */
  items: string[];
  /** Whether more pages may exist after this one. */
  hasMore: boolean;
}

export interface InfiniteListProps {
  /**
   * Fetches the next page. Resolves with the new items and whether
   * the list is exhausted. Rejects on failure.
   */
  loadMore: () => Promise<LoadResult>;
}

export function InfiniteList({ loadMore }: InfiniteListProps) {
  const [items, setItems] = useState<string[]>([]);
  const [hasMore, setHasMore] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<unknown>(null);

  // Refs mirror the async guards so the IntersectionObserver callback
  // can decide synchronously without stale closures.
  const loadingRef = useRef(false);
  const errorRef = useRef(false);
  const sentinelRef = useRef<HTMLDivElement | null>(null);

  async function trigger() {
    if (loadingRef.current || errorRef.current) return;
    loadingRef.current = true;
    setLoading(true);
    setError(null);
    try {
      const result = await loadMore();
      setItems((prev) => [...prev, ...result.items]);
      setHasMore(result.hasMore);
    } catch (err) {
      errorRef.current = true;
      setError(err);
    } finally {
      loadingRef.current = false;
      setLoading(false);
    }
  }

  useEffect(() => {
    const sentinel = sentinelRef.current;
    if (!hasMore || !sentinel) return;

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) void trigger();
        }
      },
      { rootMargin: "100px" },
    );
    observer.observe(sentinel);
    return () => observer.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasMore]);

  return (
    <div>
      <ul aria-label="items">
        {items.map((item, i) => (
          <li key={`${item}-${i}`}>{item}</li>
        ))}
      </ul>

      {error !== null && (
        <div role="alert">
          <p>Something went wrong.</p>
          <button
            onClick={() => {
              errorRef.current = false;
              setError(null);
              void trigger();
            }}
          >
            Retry
          </button>
        </div>
      )}

      {hasMore ? (
        <div ref={sentinelRef} data-testid="sentinel" aria-hidden="true" />
      ) : (
        <p>End of results</p>
      )}
    </div>
  );
}

/**
 * jsdom has no IntersectionObserver, so provide a hand-rolled mock:
 * - captures every created instance in `instances`
 * - lets tests fire entries at a specific instance via `fire()`
 */
export class MockIntersectionObserver {
  static instances: MockIntersectionObserver[] = [];

  readonly callback: IntersectionObserverCallback;
  readonly options?: IntersectionObserverInit;
  readonly observed: Element[] = [];
  disconnectMock = vi.fn();

  constructor(callback: IntersectionObserverCallback, options?: IntersectionObserverInit) {
    this.callback = callback;
    this.options = options;
    MockIntersectionObserver.instances.push(this);
  }

  observe(element: Element): void {
    this.observed.push(element);
  }

  unobserve(): void {}

  takeRecords(): IntersectionObserverEntry[] {
    return [];
  }

  disconnect(): void {
    this.disconnectMock();
  }

  /** Simulate the browser invoking this observer's callback with entries. */
  fire(isIntersecting: boolean): void {
    const entries = this.observed.map(
      (target): IntersectionObserverEntry =>
        ({ isIntersecting, target }) as unknown as IntersectionObserverEntry,
    );
    this.callback(entries, this as unknown as IntersectionObserver);
  }

  static get latest(): MockIntersectionObserver {
    return MockIntersectionObserver.instances[MockIntersectionObserver.instances.length - 1];
  }
}

globalThis.IntersectionObserver =
  MockIntersectionObserver as unknown as typeof IntersectionObserver;

