import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { InfiniteList, type LoadResult } from "../src/InfiniteList";
import { MockIntersectionObserver } from "../test-setup";

function page(items: string[], hasMore: boolean): LoadResult {
  return { items, hasMore };
}

beforeEach(() => {
  MockIntersectionObserver.reset();
});

describe("InfiniteList", () => {
  it("appends items when the sentinel intersects", async () => {
    const loadMore = vi
      .fn()
      .mockResolvedValueOnce(page(["a", "b"], true))
      .mockResolvedValueOnce(page(["c"], false));

    render(<InfiniteList loadMore={loadMore} />);
    const io = MockIntersectionObserver.latest;

    io.fire(true);
    await screen.findByText("a");
    expect(screen.getByText("b")).toBeInTheDocument();

    io.fire(true);
    await screen.findByText("c");

    expect(loadMore).toHaveBeenCalledTimes(2);
  });

  it("triggers exactly one loadMore while a request is pending", async () => {
    let resolvePending!: (r: LoadResult) => void;
    const loadMore = vi
      .fn()
      .mockImplementationOnce(() => new Promise<LoadResult>((res) => (resolvePending = res)));

    render(<InfiniteList loadMore={loadMore} />);
    const io = MockIntersectionObserver.latest;

    // Two rapid intersections while the first request is still in flight.
    io.fire(true);
    io.fire(true);

    resolvePending(page(["x"], true));
    await screen.findByText("x");

    expect(loadMore).toHaveBeenCalledTimes(1);
  });

  it("does not call loadMore again after exhaustion and disconnects the observer", async () => {
    const loadMore = vi.fn().mockResolvedValue(page(["last"], false));

    render(<InfiniteList loadMore={loadMore} />);
    const io = MockIntersectionObserver.latest;

    io.fire(true);
    expect(await screen.findByText("End of results")).toBeInTheDocument();
    expect(screen.queryByTestId("sentinel")).not.toBeInTheDocument();

    expect(io.disconnectMock).toHaveBeenCalled();

    // Further intersections are inert: no sentinel is observed anymore.
    io.fire(true);
    expect(loadMore).toHaveBeenCalledTimes(1);
  });

  it("shows a Retry button on error that re-arms loading", async () => {
    const loadMore = vi
      .fn()
      .mockRejectedValueOnce(new Error("network down"))
      .mockResolvedValueOnce(page(["recovered"], false));

    render(<InfiniteList loadMore={loadMore} />);
    const io = MockIntersectionObserver.latest;

    io.fire(true);
    expect(await screen.findByRole("alert")).toHaveTextContent("Something went wrong.");
    expect(screen.getByRole("button", { name: "Retry" })).toBeInTheDocument();

    // While errored, further intersections must not trigger anything.
    io.fire(true);
    expect(loadMore).toHaveBeenCalledTimes(1);

    await userEvent.click(screen.getByRole("button", { name: "Retry" }));

    expect(await screen.findByText("recovered")).toBeInTheDocument();
    expect(loadMore).toHaveBeenCalledTimes(2);
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();
    expect(screen.getByText("End of results")).toBeInTheDocument();
  });
});

